 static class Theme {
  public static readonly Color Background=Color.FromArgb(13,19,31),Card=Color.FromArgb(22,31,47),Border=Color.FromArgb(38,51,70),Text=Color.FromArgb(236,242,249),Muted=Color.FromArgb(139,157,181),Mint=Color.FromArgb(94,230,187),Blue=Color.FromArgb(112,167,255),Amber=Color.FromArgb(255,193,108),Red=Color.FromArgb(255,117,130);
  public static Font Font(float size,bool bold=false){return new Font("Microsoft YaHei UI",(size+1)*96f/72f,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);}
  public static Button Button(string text,bool primary=false){var b=new Button{Text=text,Height=38,Width=136,FlatStyle=FlatStyle.Flat,BackColor=primary?Mint:Card,ForeColor=primary?Background:Text,Font=Font(9,true),Cursor=Cursors.Hand,Margin=new Padding(0,0,10,0)};b.FlatAppearance.BorderColor=Border;b.FlatAppearance.BorderSize=primary?0:1;b.FlatAppearance.MouseOverBackColor=primary?Color.FromArgb(130,244,207):Color.FromArgb(34,48,68);return b;}
  public static Label Label(string text,float size=9,bool bold=false){return new Label{Text=text,AutoSize=false,Font=Font(size,bold),ForeColor=Text,BackColor=Color.Transparent};}
  public static GraphicsPath Round(Rectangle r,int radius){var p=new GraphicsPath();int d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
  public static void Write(Graphics g,string text,Font font,Color color,Rectangle rect){TextRenderer.DrawText(g,text,font,rect,color,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPadding);}
  public static string Status(Engine e,NetworkView n){return Evidence23.Describe(n,e.Config(),n.LinkFailure,DateTime.UtcNow).Title;}
  public static Color StatusColor(Engine e,NetworkView n){var status=Evidence23.Describe(n,e.Config(),n.LinkFailure,DateTime.UtcNow);return status.Severity==2?Mint:status.Severity==1?Amber:Muted;}
 }
