 sealed class TrafficChart:Control {
  readonly Queue<double> up=new Queue<double>(),down=new Queue<double>();bool available;string sampleStamp="";bool sampleService;
  public TrafficChart(){DoubleBuffered=true;Dock=DockStyle.Fill;BackColor=Theme.Card;}
  public int SampleCount {get{return up.Count;}}public bool Service;public void Add(NetworkView n){if(sampleService!=Service){up.Clear();down.Clear();sampleStamp="";sampleService=Service;}if(!String.IsNullOrEmpty(n.TrafficUtc)&&n.TrafficUtc==sampleStamp)return;sampleStamp=n.TrafficUtc;available=Service?n.ServiceTrafficValid:n.TrafficValid;up.Enqueue(available?(Service?n.ServiceUp:n.Up):0);down.Enqueue(available?(Service?n.ServiceDown:n.Down):0);while(up.Count>60){up.Dequeue();down.Dequeue();}Invalidate();}
  protected override void OnPaint(PaintEventArgs ev){var g=ev.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var f=Theme.Font(10,true))Theme.Write(g,(Service?"OpenAI 关联流量（估算）":"实时代理流量"),f,Theme.Text,new Rectangle(18,10,200,28));using(var f=Theme.Font(8))Theme.Write(g,"下载  /  上传    ·    最近 60 个采样",f,Theme.Muted,new Rectangle(Width-292,10,270,28));
   Rectangle r=new Rectangle(20,51,Math.Max(1,Width-42),Math.Max(1,Height-80));using(var pen=new Pen(Theme.Border)){for(int i=0;i<4;i++)g.DrawLine(pen,r.Left,r.Top+i*r.Height/3,r.Right,r.Top+i*r.Height/3);}
   double max=Math.Max(1024,Math.Max(up.DefaultIfEmpty(0).Max(),down.DefaultIfEmpty(0).Max())*1.15);Plot(g,down.ToArray(),r,max,Theme.Mint,true);Plot(g,up.ToArray(),r,max,Theme.Blue,false);
   using(var f=Theme.Font(8)){Theme.Write(g,NodePolicy.Rate(max),f,Theme.Muted,new Rectangle(r.Left+4,r.Top,150,20));Theme.Write(g,available?(Service?"域名关联估算，可能包含浏览器和探测":"全代理流量，非 Codex 独占流量"):"暂无速率数据，等待采样",f,Theme.Muted,new Rectangle(20,Height-25,Width-40,20));}
  }
  static void Plot(Graphics g,double[] samples,Rectangle r,double max,Color color,bool fill){if(samples.Length<2)return;var points=samples.Select((v,i)=>new PointF(r.Left+(float)i*r.Width/59,r.Bottom-(float)Math.Min(1,v/max)*r.Height)).ToArray();if(fill){var polygon=new List<PointF>{new PointF(points[0].X,r.Bottom)};polygon.AddRange(points);polygon.Add(new PointF(points[points.Length-1].X,r.Bottom));using(var b=new SolidBrush(Color.FromArgb(20,color)))g.FillPolygon(b,polygon.ToArray());}using(var pen=new Pen(color,2f))g.DrawLines(pen,points);}
 }
