  void UpdateEnhancementViews(Settings c,NetworkView n){bool wasLoading=loading;loading=true;topMostCheck.Checked=c.FloatingTopMost;compactCheck.Checked=c.FloatingCompact;edgeCheck.Checked=c.FloatingAutoHide;lockCheck.Checked=c.FloatingLocked;serviceCheck.Checked=c.FloatingServiceTraffic;fullscreenCheck.Checked=c.HideFloatingFullscreen;notifyCheck.Checked=c.NotifyProblems;if(!scaleInput.Focused)scaleInput.Value=FloatGeometry.Scale(c);if(!opacityInput.Focused)opacityInput.Value=FloatGeometry.Opacity(c);loading=wasLoading;var progress=monitor.Progress;progressLabel.Text=PausePolicy.Active(c,DateTime.UtcNow)?"自动恢复暂停至 "+Presentation.When(c.RecoveryPauseUntilUtc)+" · 剩余 "+Math.Ceiling(PausePolicy.Remaining(c,DateTime.UtcNow)/60.0)+" 分钟":progress.Active?progress.Text(DateTime.UtcNow):String.IsNullOrEmpty(progress.Phase)?"自动恢复待命 · 同国优先，全部确认故障才跨国":progress.Text(DateTime.UtcNow);var rows=monitor.History();string signature=rows.Length+"|"+(rows.Length==0?"":rows[rows.Length-1].AtUtc);if(signature!=historyStamp){historyStamp=signature;historyGrid.Rows.Clear();foreach(var row in rows.Reverse())historyGrid.Rows.Add(Presentation.When(row.AtUtc),row.From,row.To,row.Result,row.Seconds,row.Group,row.Reason);}
   var info=monitor.Exit;exitLabel.Text=monitor.ExitBusy?"正在只读查询当前出口资料…":info==null?"出口地区尚未查询；节点国家仍按名称识别。":info.Node!=n.Node||info.Group!=n.Group||info.Mode!=n.Mode?"节点或路径已变化，请重新查询出口资料。":(String.IsNullOrEmpty(info.CountryCode)?"地区资料未确认":NodePolicy.CountryText(info.CountryCode)+" / "+info.CountryCode+" · "+info.MaskedIp)+"\n"+info.Detail+" · "+Presentation.When(info.CheckedUtc);}
  public void ShowPage(string key){foreach(var pair in pages)pair.Value.Visible=pair.Key==key;foreach(var pair in nav){pair.Value.BackColor=pair.Key==key?Color.FromArgb(30,53,56):Color.FromArgb(16,24,38);pair.Value.ForeColor=pair.Key==key?Theme.Mint:Theme.Muted;}subheading.Text=key;if(key=="使用记录"){recordRefresh=DateTime.MinValue;RefreshDiagnostics();}}
  void PopulateGroups(){var view=monitor.View;string signature=view.Mode+"|"+view.Group+"|"+String.Join("|",view.Nodes.Where(p=>p.Value.Type=="Selector").Select(p=>p.Key+":"+String.Join(",",p.Value.Members)));if(signature==lastCatalog)return;lastCatalog=signature;loading=true;group.Items.Clear();if(!String.IsNullOrEmpty(view.Group)&&view.Nodes.ContainsKey(view.Group))group.Items.Add(view.Group);if(group.Items.Count>0)group.SelectedIndex=0;group.Enabled=false;loading=false;PopulateCountries();}
  void PopulateCountries(){string selected=Convert.ToString(country.SelectedItem);if(String.IsNullOrEmpty(selected))selected=engine.Config().LockedCountry;string name=Convert.ToString(group.SelectedItem);loading=true;country.Items.Clear();if(monitor.View.Nodes.ContainsKey(name))foreach(string code in monitor.View.Nodes[name].Members.Where(x=>monitor.View.Nodes.ContainsKey(x)&&monitor.View.Nodes[x].IsLeaf).Select(NodePolicy.Country).Where(x=>x.Length>0&&(!engine.Config().AllowCountryFallback||CountryFallback.Supported(x))).Distinct().OrderBy(x=>x))country.Items.Add(code);if(country.Items.Contains(selected))country.SelectedItem=selected;loading=false;PopulateNodes();}
  void PopulateNodes(){string name=Convert.ToString(group.SelectedItem),code=Convert.ToString(country.SelectedItem);Settings c=engine.Config();c.ManagedGroup=name;c.LockedCountry=code;var selected=CountryPolicy.Effective(monitor.View,c);populatingNodes=true;try{nodes.Items.Clear();foreach(string node in CountryPolicy.Members(monitor.View,name,code))nodes.Items.Add(node,selected.Contains(node));}finally{populatingNodes=false;}UpdateSelectionInfo();}
  void UpdateSelectionInfo(){selectionInfo.Text="国家节点自动纳入 · 已选 "+nodes.CheckedItems.Count+" / "+nodes.Items.Count+" 个 · "+NodePolicy.CountryText(Convert.ToString(country.SelectedItem))+"（名称推断）";}
  void PersistChoice(){string name=Convert.ToString(group.SelectedItem),code=Convert.ToString(country.SelectedItem);engine.Update(c=>{c.ManagedGroup=name;c.LockedCountry=code;c.AutoCountryWhitelist=true;c.AllowedNodes=CountryPolicy.Effective(monitor.View,c);});Notice(code.Length>0?"国家和候选规则已自动保存，重启后恢复；手动排除的节点会保留。":"请选择锁定国家；选择后默认纳入该国节点。");monitor.Request();}
  void PersistNodeCheck(ItemCheckEventArgs args){var selected=nodes.CheckedItems.Cast<string>().ToList();string name=Convert.ToString(nodes.Items[args.Index]);selected.Remove(name);if(args.NewValue==CheckState.Checked)selected.Add(name);string policyGroup=Convert.ToString(group.SelectedItem),code=Convert.ToString(country.SelectedItem);engine.Update(c=>CountryPolicy.SetSelection(c,monitor.View,policyGroup,code,selected.ToArray()));Notice("候选选择已自动保存；新加入的同国家节点自动纳入。");}
  void SavePolicy(){if(country.SelectedIndex<0){Notice("请先选择锁定国家，国家节点将默认全选并自动保存。");return;}PersistChoice();monitor.Request();Notice("策略已自动保存；"+NodePolicy.BlockReason(monitor.View,engine.Config()));}
  void Notice(string text){notice.Text=text;noticeUntil=DateTime.UtcNow.AddSeconds(7);}
  public void RefreshView(){RefreshDiagnostics();var v=engine.View;var n=monitor.View;Settings c=engine.Config();if(floatingCheck.Checked!=c.ShowFloating){loading=true;floatingCheck.Checked=c.ShowFloating;loading=false;}pause.Text=c.Paused?"恢复守护":"暂停守护";restart.Text=v.ForceRequired?"强制重启 Codex":"重启 Codex";delay.Enabled=!String.IsNullOrEmpty(v.RestartDueUtc);hero.Invalidate();bool service=c.FloatingServiceTraffic,valid=service?n.ServiceTrafficValid:n.TrafficValid;download.Caption=service?"OpenAI 关联下载":"下载速率";upload.Caption=service?"OpenAI 关联上传":"上传速率";download.Value=valid?NodePolicy.Rate(service?n.ServiceDown:n.Down):"—";upload.Value=valid?NodePolicy.Rate(service?n.ServiceUp:n.Up):"—";download.Detail=upload.Detail=service?"域名估算，含探测":"代理总流量";chart.Service=service;latency.Value=n.Delay>=0?n.Delay+" ms":"—";latency.Detail=n.ProbeKnown?"节点 HTTP 探测":"等待节点探测";connections.Value=n.Controller?n.Connections.ToString():"—";connections.Detail=n.TrafficValid?"采样 "+Math.Max(0,(int)(DateTime.UtcNow-Files.Date(n.TrafficUtc)).TotalSeconds)+" 秒前":"流量数据已过期，等待更新";latency.Detail=n.ProbeKnown?"探测 "+Math.Max(0,(int)(DateTime.UtcNow-Files.Date(n.ProbeUtc)).TotalSeconds)+" 秒前":"等待新路径探测";foreach(var m in new[]{download,upload,latency,connections})m.Invalidate();chart.Add(n);PopulateGroups();
   if(countryFallback.Checked&&country.Items.Contains(c.LockedCountry)&&Convert.ToString(country.SelectedItem)!=c.LockedCountry){loading=true;country.SelectedItem=c.LockedCountry;loading=false;PopulateNodes();}string reason=NodePolicy.BlockReason(n,c);recoveryInfo.Text=reason.Length>0?"状态："+reason:(c.AllowCountryFallback?"状态：日新恢复待命 · 本国全部确认失败才跨国 · 异常累计与复测":"状态：同国恢复待命 · 连续 3 轮失败后尝试");
   if(monitor.Coverage.Length>0)recoveryInfo.Text+=" · "+monitor.Coverage;if(monitor.RecoveryWait.Length>0)recoveryInfo.Text+=" · "+monitor.RecoveryWait;
   probeInfo.Text=(Evidence23.AppResponse(n,DateTime.UtcNow)?"已有应用连接：下行有响应，实际节点 "+n.AppResponseNode:"已有应用连接：暂无近期下行证据；空闲不代表断网")+"\n新连接探测 · ChatGPT："+Evidence23.Target(n,true,DateTime.UtcNow)+"\n新连接探测 · Codex 环境："+Evidence23.Target(n,false,DateTime.UtcNow);
   if(!String.IsNullOrEmpty(v.RestartDueUtc)||!String.IsNullOrEmpty(n.Error)||!String.IsNullOrEmpty(v.LastError)||DateTime.UtcNow>=noticeUntil){if(!String.IsNullOrEmpty(v.RestartDueUtc))notice.Text=v.ForceRequired?"Codex 未正常退出，已保留进程；可手动退出或选择强制重启。":"Codex 重启计划："+(c.Paused?"已暂停":"约 "+Math.Ceiling(Math.Max(0,(Files.Date(v.RestartDueUtc)-DateTime.UtcNow).TotalSeconds))+" 秒后执行，可在偏好设置中延后。");else if(!String.IsNullOrEmpty(n.Error))notice.Text=n.Error;else if(!String.IsNullOrEmpty(v.LastError))notice.Text=v.LastError;else notice.Text=monitor.Automation.Text;
   }
   UpdateEnhancementViews(c,n);
   if(DateTime.UtcNow>=logDue){logDue=DateTime.UtcNow.AddSeconds(3);try{string path=Path.Combine(Program.Root,"guard.log");string text=File.Exists(path)?String.Join(Environment.NewLine,File.ReadLines(path).Reverse().Take(100).Reverse()):"暂无日志";if(logText!=text){log.Text=text;logText=text;log.SelectionStart=log.TextLength;log.ScrollToCaret();}}catch{}}
   if(Floating!=null)Floating.UpdateView();
  }
  string DiagnosticText(){var n=monitor.View;var v=engine.View;var h=v.Health??new Health();var b=new StringBuilder();b.AppendLine("Codex 代理管理器 2.6");b.AppendLine("时间："+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"));b.AppendLine("守护："+v.Mode+" / Codex PID "+v.CodexPid);b.AppendLine("代理："+v.ObservedProxy);b.AppendLine("模式 / 策略组："+n.Mode+" / "+n.Group);b.AppendLine("节点："+n.Node);b.AppendLine("规则入口："+n.RuleRoot+" / 选择组："+n.RuleOwner);b.AppendLine("路线依据："+n.RuleSource+" / 实测 UTC："+n.RuleEvidenceUtc);b.AppendLine("识别说明："+n.RuleIssue);b.AppendLine("地区："+NodePolicy.CountryText(n.Country)+"（名称推断，出口未核验）");b.AppendLine("代理总流量：↑ "+(n.TrafficValid?NodePolicy.Rate(n.Up):"未知")+" / ↓ "+(n.TrafficValid?NodePolicy.Rate(n.Down):"未知"));b.AppendLine("节点探测："+Theme.Status(engine,n));b.AppendLine("判断依据："+monitor.Status.Detail);b.AppendLine("自动处理："+monitor.Automation.Text);b.AppendLine("当前事件编号："+monitor.Automation.Id);b.AppendLine("本次记录编号："+monitor.Journal.Session);b.AppendLine("记录状态："+monitor.Journal.Summary());b.AppendLine("失败日志："+n.LogFeed);b.AppendLine("候选范围："+monitor.Coverage);b.AppendLine("恢复等待："+monitor.RecoveryWait);b.AppendLine("OpenAI 关联估算：↑ "+(n.ServiceTrafficValid?NodePolicy.Rate(n.ServiceUp):"未知")+" / ↓ "+(n.ServiceTrafficValid?NodePolicy.Rate(n.ServiceDown):"未知"));b.AppendLine("服务关联连接："+n.ServiceConnections);b.AppendLine("服务最近传输 UTC："+n.LastServiceActivityUtc);b.AppendLine("国家候选规则：自动保存 / 动态纳入同国家节点");b.AppendLine("跨国规则："+(engine.Config().AllowCountryFallback?"仅日本与新加坡；本国全部节点双重失败才跨国":"关闭"));b.AppendLine("恢复："+recoveryInfo.Text);b.AppendLine("恢复进度："+monitor.Progress.Text(DateTime.UtcNow));b.AppendLine("临时暂停截止 UTC："+engine.Config().RecoveryPauseUntilUtc);foreach(var endpoint in h.Endpoints)b.AppendLine(endpoint.Name+"："+endpoint.Detail);b.AppendLine("匿名探测不验证登录或对话流。0 流量不代表断网。");return b.ToString();}
  public void ToggleFloating(){bool show=!engine.Config().ShowFloating;engine.Update(c=>c.ShowFloating=show);loading=true;floatingCheck.Checked=show;loading=false;if(Floating!=null){if(show)Floating.Show();else Floating.Hide();}}
  public void ShowManager(){Show();WindowState=FormWindowState.Normal;Activate();Native.SetForegroundWindow(Handle);}
  public void AllowExit(){allowExit=true;timer.Stop();}
  public void RemoveProgram(){try{Program.CleanupBuild();Startup.RestoreProxyShortcut();Startup.Remove();monitor.Dispose();engine.Dispose();Program.RemoveAfterExit();AllowExit();Application.Exit();}catch(Exception e){Notice("卸载未完成："+e.Message);}}
  protected override void Dispose(bool disposing){if(disposing){timer.Dispose();if(ownsMonitor)monitor.Dispose();}base.Dispose(disposing);}
 }
